def serialize_tree(expression: str) -> float:
    """Evaluate a postfix (Reverse Polish Notation) expression.

    Args:
        expression: Space-separated postfix expression string.
            Supported operators: +, -, *, /, ** (power), % (modulo).

    Returns:
        The numeric result of evaluating the expression.

    Raises:
        ValueError: If the expression is malformed or contains division by zero.
    """
    tokens = expression.split()
    stack = []
    operators = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: a / b,
        '**': lambda a, b: a ** b,
        '%': lambda a, b: a % b,
    }

    for token in tokens:
        if token in operators:
            if len(stack) < 2:
                raise ValueError(f"Insufficient operands for operator '{token}'")
            b = stack.pop()
            a = stack.pop()
            if token == '/' and b == 0:
                raise ValueError("Division by zero")
            stack.append(operators[token](a, b))
        else:
            try:
                stack.append(float(token))
            except ValueError:
                raise ValueError(f"Invalid token: '{token}'")

    if len(stack) != 1:
        raise ValueError("Malformed expression: too many operands")

    return stack[0]


